function getResult(str) {
  const regExp = /(\d+)#(\d+)/;

  while (str.indexOf("#") !== -1) {
    str = str.replace(
      regExp,
      (_, x, y) => 4 * parseInt(x) + 3 * parseInt(y) + 2
    );
  }

  return str.split("$").reduce((x, y) => 2 * parseInt(x) + parseInt(y) + 3);
}

